import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Help Desk — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Help Desk — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/help-desk"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Help Desk — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/help-desk"}]]},"headers":[],"relativePath":"user-guide/help-desk.md","filePath":"user-guide/help-desk.md","lastUpdated":1788177880000}'),n={name:"user-guide/help-desk.md"};function r(i,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="help-desk-—-user-guide" tabindex="-1">Help Desk — User Guide <a class="header-anchor" href="#help-desk-—-user-guide" aria-label="Permalink to &quot;Help Desk — User Guide&quot;">​</a></h1><h2 id="who-can-use-help-desk" tabindex="-1">Who can use Help Desk <a class="header-anchor" href="#who-can-use-help-desk" aria-label="Permalink to &quot;Who can use Help Desk&quot;">​</a></h2><p>Enable the <strong>Help Desk</strong> module from Marketplace (free) — no other modules are required first. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>close</code>, <code>reopen</code> as needed).</p><p>Without <strong>assign</strong>, you only see tickets assigned to you.</p><blockquote><p>Help Desk is for <strong>internal workspace support</strong>. To report bugs or request platform features, use <a href="/user-guide/feedback">Give Feedback</a> — that flow is triaged in Central, not in Help Desk.</p></blockquote><h2 id="list-board-table" tabindex="-1">List, board &amp; table <a class="header-anchor" href="#list-board-table" aria-label="Permalink to &quot;List, board &amp; table&quot;">​</a></h2><p>Open <strong>Help Desk</strong> from the sidebar, under the <strong>Operations</strong> group. Switch <strong>Board</strong> / <strong>List</strong> in the page header (defaults to Board, same pattern as Tasks). On the board, columns are the fixed statuses Open → In Progress → Waiting → Resolved → Closed; drag a card to change status (honors update / close / reopen permissions and the status workflow). Search by subject, number, or description; filter by status, priority, category, or SLA (breached / at risk); toggle <strong>My Tickets</strong> or <strong>Overdue</strong>; and switch KPI cards (including <strong>SLA breached</strong> / <strong>SLA at risk</strong>) to quick-filter. The list table shows category, status, priority, SLA badge, source (Email), assignee, due date, and the <strong>latest note</strong>.</p><p>Use <strong>Manage categories</strong> (visible with <code>help-desk.create</code>, <code>help-desk.update</code>, or <code>help-desk.delete</code>) to add, rename, activate/deactivate, or delete workspace ticket categories. New workspaces start with General, Technical, Billing, Account, and Other. You cannot delete <strong>Other</strong> (default for new tickets). You also cannot delete a category that still has tickets. Renaming a starter category keeps its slug.</p><p>Use <strong>Manage SLAs</strong> to define response and resolve targets (minutes) optionally scoped by category and/or priority. The most specific matching active policy applies when a ticket is created (or when priority/category changes while still open). Breaches notify the assignee and appear in the list/KPIs.</p><p>Use <strong>Manage mailboxes</strong> to connect a shared support IMAP inbox (separate from personal Email accounts). New inbound mail creates a ticket (<code>source=email</code>); replies that mention the ticket number (e.g. <code>HD-00042</code>) append an unauthored note. When Contacts is installed, new tickets soft-link a contact whose email matches the sender.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted ticket from the row menu</li><li><strong>Delete permanently</strong> requires <code>help-desk.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="dashboard-widget" tabindex="-1">Dashboard widget <a class="header-anchor" href="#dashboard-widget" aria-label="Permalink to &quot;Dashboard widget&quot;">​</a></h2><p>When Help Desk is installed and you have <code>help-desk.view</code>, the dashboard may show <strong>My open tickets</strong> (<code>help_desk_my_open</code>) — open tickets assigned to you, with a link to the full list.</p><h2 id="create-a-ticket" tabindex="-1">Create a ticket <a class="header-anchor" href="#create-a-ticket" aria-label="Permalink to &quot;Create a ticket&quot;">​</a></h2><ol><li>Click <strong>New ticket</strong></li><li>Enter a subject and optional description</li><li>Choose category (from your workspace list) and priority</li><li>Optionally set a due date (interpreted in your workspace timezone)</li><li>If <strong>Contacts</strong> or <strong>Companies</strong> are installed, optionally link a contact and/or company</li><li>If <strong>Knowledge Base</strong> is installed, optionally link one or more articles (published articles for view-only users; editors with <code>knowledge-base.update</code> can also link drafts)</li><li>Optionally set an assignee (requires <strong>assign</strong>); otherwise the ticket defaults to you</li><li>Save</li></ol><p>Edit from the row menu or the ticket page while the ticket is not <strong>Closed</strong>. Closed tickets must be <strong>Reopened</strong> before content edits.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A ticket starts <strong>Open</strong>. Move it forward with status actions or the status picker:</p><ul><li><strong>In progress</strong> (<code>open → in_progress</code>)</li><li><strong>Waiting</strong> (<code>open | in_progress → waiting</code>) — e.g. blocked on customer reply</li><li><strong>Resolved</strong> (<code>open | in_progress | waiting → resolved</code>)</li><li><strong>Close</strong> (<code>open | in_progress | waiting | resolved → closed</code>) — requires <code>help-desk.close</code></li><li><strong>Reopen</strong> (<code>resolved → open</code> or <code>closed → open</code>) — requires <code>help-desk.reopen</code></li></ul><p>Invalid transitions are rejected with a validation error. Use <strong>Close</strong> for a terminal closed state; <strong>Resolved</strong> can still move to <strong>Closed</strong> or back to <strong>Open</strong>.</p><h2 id="optional-contact-company-links" tabindex="-1">Optional contact / company links <a class="header-anchor" href="#optional-contact-company-links" aria-label="Permalink to &quot;Optional contact / company links&quot;">​</a></h2><p>Both links are <strong>soft</strong> — they only appear in the create/edit form when the corresponding module (<strong>Contacts</strong> / <strong>Companies</strong>) is installed on your workspace, and they&#39;re always optional even when installed. A ticket without either link works the same; the links are for cross-referencing to CRM records.</p><h2 id="optional-knowledge-base-links" tabindex="-1">Optional Knowledge Base links <a class="header-anchor" href="#optional-knowledge-base-links" aria-label="Permalink to &quot;Optional Knowledge Base links&quot;">​</a></h2><p>When <strong>Knowledge Base</strong> is installed, the create/edit form shows a <strong>Knowledge base articles</strong> multi-select. Linked articles appear under <strong>Related articles</strong> on the ticket view (links open the article record). On the article view, <strong>Linked tickets</strong> lists tickets that reference that article when Help Desk is also installed. No hard module dependency — either module can be installed without the other; links are simply unavailable until both are entitled.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the ticket page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-timeline" tabindex="-1">Notes &amp; timeline <a class="header-anchor" href="#notes-timeline" aria-label="Permalink to &quot;Notes &amp; timeline&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form internal notes on the ticket</li><li><strong>Timeline</strong> — history of create, update, assignment, status change, note, and delete/restore events</li></ul><h2 id="due-dates-overdue" tabindex="-1">Due dates &amp; overdue <a class="header-anchor" href="#due-dates-overdue" aria-label="Permalink to &quot;Due dates &amp; overdue&quot;">​</a></h2><p>Set an optional <strong>due date</strong> on create or edit. Overdue filtering and KPIs compare <code>due_at</code> against the current instant using the workspace timezone convention (same as Tasks and Leads follow-ups). Tickets in <strong>Resolved</strong> or <strong>Closed</strong> are excluded from the overdue count.</p><h2 id="slas" tabindex="-1">SLAs <a class="header-anchor" href="#slas" aria-label="Permalink to &quot;SLAs&quot;">​</a></h2><p>Define policies under <strong>Manage SLAs</strong>. Each policy sets first-response and resolve targets in minutes, optionally limited to a category and/or priority. Open tickets get response/resolve clocks; the first staff note or status leave from <strong>Open</strong> counts as first response. Breached tickets notify the assignee and show on the list/KPIs. Manual <code>due_at</code> remains independent of SLA clocks.</p><h2 id="email-intake" tabindex="-1">Email intake <a class="header-anchor" href="#email-intake" aria-label="Permalink to &quot;Email intake&quot;">​</a></h2><p><strong>Manage mailboxes</strong> connects a shared support IMAP account for the workspace (not the personal Email module). New messages create tickets marked <strong>Email</strong>; replies that include the ticket number append a note. Sync runs on a schedule and can be triggered manually.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Customer portal and chat/social intake channels are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>. Ticket notes support <code>@mentions</code>. Use <strong>Board</strong> / <strong>List</strong> for status Kanban. Soft-gated WhatsApp Communication Templates appear on ticket view when that module is installed and the contact has a phone.</p><p>When <strong>Communication Templates</strong> is installed and you have <code>communication-templates.use</code>, open a ticket with a linked contact that has a phone number and click <strong>WhatsApp</strong> to pick a Help Desk template (or a blank chat). EloSync opens WhatsApp Web/app with the message pre-filled — it does not send messages for you.</p>',37)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
